    "api_key_err": "Gagal memuat kunci:",
    "api_ep_title": "Endpoint",
    "api_ep_models": "Menampilkan daftar model yang tersedia.",
    "api_ep_chat": "Obrolan. Field: messages, stream, temperature, max_tokens, stop.",
