    "err_fim_name": "Ongeldige naam van het automatisch-aanvullenmodel (gebruik een .gguf-bestand uit de modelmap).",
    "err_fim_path": "Ongeldig pad van het automatisch-aanvullenmodel: gebruik het volledige pad van een .gguf-bestand.",
